import React, { useState, useEffect, useRef } from 'react';
import api from '../api';
import TaskItem from './TaskItem';
import ChecklistView from './ChecklistView';

function Tasks({ selectedDate, onDateChange }) {
  const [tasks, setTasks] = useState({ daily: { checklists: [], standaloneTasks: [] }, weekly: { checklists: [], standaloneTasks: [] }, monthly: { checklists: [], standaloneTasks: [] } });
  const [loading, setLoading] = useState(true);
  const [selectedChecklist, setSelectedChecklist] = useState(null);
  const scrollPositionRef = useRef(0);

  useEffect(() => {
    loadTasks();
  }, [selectedDate]);

  // Save scroll position before updates
  const saveScrollPosition = () => {
    scrollPositionRef.current = window.scrollY;
  };

  // Restore scroll position after updates
  useEffect(() => {
    if (scrollPositionRef.current > 0) {
      window.scrollTo(0, scrollPositionRef.current);
    }
  }, [tasks]);

  const loadTasks = async () => {
    setLoading(true);
    try {
      const data = await api.getTasksForDate(selectedDate);
      setTasks(data);
    } catch (error) {
      console.error('Error loading tasks:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleTaskUpdate = () => {
    saveScrollPosition();
    loadTasks();
  };

  const formatDateForDisplay = (dateStr) => {
    const [year, month, day] = dateStr.split('-');
    return `${month}/${day}/${year}`;
  };

  const handleDateChange = (e) => {
    const input = e.target.value.replace(/\D/g, '');

    if (input.length >= 8) {
      const month = input.substring(0, 2);
      const day = input.substring(2, 4);
      const year = input.substring(4, 8);

      const monthNum = parseInt(month);
      const dayNum = parseInt(day);

      if (monthNum >= 1 && monthNum <= 12 && dayNum >= 1 && dayNum <= 31) {
        const dateStr = `${year}-${month}-${day}`;
        onDateChange(dateStr);
      }
    }

    let formatted = input;
    if (input.length >= 2) {
      formatted = input.substring(0, 2) + '/' + input.substring(2);
    }
    if (input.length >= 4) {
      formatted = input.substring(0, 2) + '/' + input.substring(2, 4) + '/' + input.substring(4, 8);
    }

    e.target.value = formatted;
  };

  const handlePrevDay = () => {
    const date = new Date(selectedDate);
    date.setDate(date.getDate() - 1);
    onDateChange(date.toISOString().split('T')[0]);
  };

  const handleNextDay = () => {
    const date = new Date(selectedDate);
    date.setDate(date.getDate() + 1);
    onDateChange(date.toISOString().split('T')[0]);
  };

  const handleChecklistClick = (checklist) => {
    setSelectedChecklist(checklist);
  };

  const handleBackFromChecklist = () => {
    setSelectedChecklist(null);
    loadTasks();
  };

  if (selectedChecklist) {
    return (
      <ChecklistView
        checklist={selectedChecklist}
        tasks={tasks}
        onBack={handleBackFromChecklist}
        onUpdate={handleTaskUpdate}
      />
    );
  }

  if (loading) {
    return <div className="loading">Loading tasks...</div>;
  }

  const renderTaskSection = (title, taskData) => {
    const { checklists, standaloneTasks } = taskData;

    if (checklists.length === 0 && standaloneTasks.length === 0) {
      return null;
    }

    return (
      <div className="task-section">
        <div className="section-header">
          <h2>{title}</h2>
        </div>

        {checklists.map((checklist) => (
          <div 
            key={checklist.id} 
            className="checklist-container"
            onClick={() => handleChecklistClick(checklist)}
            style={{ cursor: 'pointer' }}
          >
            <div className="checklist-header">
              <h3>{checklist.name}</h3>
              {checklist.description && <p className="checklist-description">{checklist.description}</p>}
            </div>
            <div className="checklist-tasks">
              {checklist.tasks.map((task) => (
                <TaskItem 
                  key={task.id} 
                  task={task} 
                  onUpdate={handleTaskUpdate}
                  isInChecklist={true}
                />
              ))}
            </div>
          </div>
        ))}

        {standaloneTasks.map((task) => (
          <TaskItem 
            key={task.id} 
            task={task} 
            onUpdate={handleTaskUpdate}
            isInChecklist={false}
          />
        ))}
      </div>
    );
  };

  return (
    <div className="main-content">
      <div className="page-header">
        <h1>My Tasks</h1>
        <div className="date-selector">
          <button className="btn btn-secondary" onClick={handlePrevDay}>←</button>
          <input
            type="text"
            className="form-control date-input"
            defaultValue={formatDateForDisplay(selectedDate)}
            onChange={handleDateChange}
            placeholder="MM/DD/YYYY"
            maxLength="10"
          />
          <button className="btn btn-secondary" onClick={handleNextDay}>→</button>
        </div>
      </div>

      {renderTaskSection('Daily Tasks', tasks.daily)}
      {renderTaskSection('Weekly Tasks', tasks.weekly)}
      {renderTaskSection('Monthly Tasks', tasks.monthly)}

      {tasks.daily.checklists.length === 0 && 
       tasks.daily.standaloneTasks.length === 0 &&
       tasks.weekly.checklists.length === 0 && 
       tasks.weekly.standaloneTasks.length === 0 &&
       tasks.monthly.checklists.length === 0 && 
       tasks.monthly.standaloneTasks.length === 0 && (
        <div className="no-tasks">
          <p>No tasks for this date</p>
        </div>
      )}
    </div>
  );
}

export default Tasks;
